CREATE AGGREGATE p363315g3410gg1(val DOUBLE) RETURNS DOUBLE LANGUAGE CPP {
    double sum = 0.0, mean, variance = 0.0;
    for (double num : val) sum += num;
    mean = sum / val.size();
    for (double num : val) variance += pow(num - mean, 2);
    return variance / val.size();
};

