CREATE AGGREGATE p363315g3544gg1(val INTEGER) RETURNS INTEGER LANGUAGE CPP {
    int sum = 0;
    int count = 0;
    for (int i = 0; i < aggr_group_size; i++) {
        sum += val[i];
        count++;
    }
    return sum / count;
};

