CREATE AGGREGATE p363315g3546gg1(val INTEGER) RETURNS INTEGER LANGUAGE CPP {
    int max_val = INT_MIN;
    for (int i = 0; i < aggr_group_size; i++) {
        if (val[i] > max_val) {
            max_val = val[i];
        }
    }
    return max_val;
};

