CREATE AGGREGATE p363315g3549gg1(val DOUBLE) RETURNS DOUBLE LANGUAGE CPP {
    double sum = 0.0;
    double sum_sq = 0.0;
    for (int i = 0; i < aggr_group_size; i++) {
        sum += val[i];
        sum_sq += val[i] * val[i];
    }
    double mean = sum / aggr_group_size;
    return (sum_sq / aggr_group_size) - (mean * mean);
};

CREATE AGGREGATE p363315g3550gg1(val DOUBLE) RETURNS DOUBLE LANGUAGE CPP {
    double sum = 0.0;
    double sum_sq = 0.0;
    for (int i = 0; i < aggr_group_size; i++) {
        sum += val[i];
        sum_sq += val[i] * val[i];
    }
    double mean = sum / aggr_group_size;
    double variance = (sum_sq / aggr_group_size) - (mean * mean);
    return sqrt(variance);
};

CREATE AGGREGATE p363315g3551gg1(val INTEGER) RETURNS INTEGER LANGUAGE CPP {
    std::vector<int> values(val, val + aggr_group_size);
    std::sort(values.begin(), values.end());
    if (aggr_group_size % 2 == 0) {
        return (values[aggr_group_size / 2 - 1] + values[aggr_group_size / 2]) / 2;
    } else {
        return values[aggr_group_size / 2];
    }
};

CREATE AGGREGATE p363315g3552gg1(val INTEGER) RETURNS INTEGER LANGUAGE CPP {
    std::unordered_map<int, int> freq;
    for (int i = 0; i < aggr_group_size; i++) {
        freq[val[i]]++;
    }
    int mode = val[0];
    int max_count = 1;
    for (const auto &pair : freq) {
        if (pair.second > max_count) {
            max_count = pair.second;
            mode = pair.first;
        }
    }
    return mode;
};

CREATE AGGREGATE p363315g3553gg1(val DOUBLE, q DOUBLE) RETURNS DOUBLE LANGUAGE CPP {
    std::vector<double> values(val, val + aggr_group_size);
    std::sort(values.begin(), values.end());
    double index = q * (aggr_group_size - 1);
    int lower = static_cast<int>(index);
    double fraction = index - lower;
    if (lower + 1 < aggr_group_size) {
        return values[lower] + fraction * (values[lower + 1] - values[lower]);
    } else {
        return values[lower];
    }
};

